{"code_completion": "module TopModule (
    input clk,
    input reset,
    input [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);
    localparam LOW   = 2'd0;
    localparam MID1  = 2'd1;
    localparam MID2  = 2'd2;
    localparam HIGH  = 2'd3;

    reg [1:0] current, previous;
    wire [1:0] next_level;

    assign next_level = s[2] ? HIGH :
                        s[1] ? MID2 :
                        s[0] ? MID1 : LOW;

    always @(posedge clk) begin
        if (reset) begin
            current  <= LOW;
            previous <= LOW;
        end else begin
            if (next_level != current) begin
                previous <= current;
                current  <= next_level;
            end
        end
    end

    assign fr0 = (current != HIGH);
    assign fr1 = (current == LOW || current == MID1);
    assign fr2 = (current == LOW);

    assign dfr = (current == LOW) ||
                 ((current == MID1 || current == MID2) && (previous < current));
endmodule"}
